  .input(z.object({ path: z.string() }))
  .output(z.object({ ok: z.boolean(), report: z.string() }))
  .runner(local)
  .effect('repeatable')
  .run(async (input, ctx) => {
    const result = await ctx.exec(['./bin/validate', input.path]);
    return { ok: result.code === 0, report: result.stdout };
  });

