    }),
  )
  .store(sqlite.store<NightlyLoadData>('.harness/loads.sqlite'))
  .handle(nightlyFlow, {
    exits: { loaded, warnings: loadedWithWarnings, rejected },
    retry: { retries: 0, backoff: 'none', exhausted: failed },
  });

