      on: H.events.transitions(incidents),
      text: event => `Incident ${event.unit.key} "${event.unit.data.title}": ${event.from ?? 'new'} → ${event.to}`,
    }),
    observers.board({ path: 'BOARD.md' }),
  );

void operations.start();
