      if (!response.ok) throw new Error(`citation does not resolve: ${url}`);
    }
  });

const publishReport = H.command('publishReport')
  .input(z.object({ slug: z.string(), report: z.string() }))
  .runner(local)
  .effect('repeatable')
  .run(async (input, ctx) => {
