    status: 'candidate',
  })));

const editor = claudeCode.client('editor');

export const harness = H.harness('content-review')
  .ledger(sqlite.ledger('.harness/ledger.db'))
  .pools(apiPool)
  .lanes(drafts)
  .journals(tasteJournal, factJournal)
  .triggers(notesBecomeTaste)
  .grants(H.grant(
