  const startable = view.pending.filter(unit => !(incidentOpen && unit.is(Backup)));
  return {
    start: [...startable].sort((a, b) => rank(a) - rank(b)),
    preempt: incidentPending ? view.active.filter(unit => !unit.is(Backup) && !unit.is(Incident)) : [],
  };
});

