  if (cheaper.samples < 20) return [sonnet, opus];
  return (cheaper.value ?? 0) < 0.85 ? [opus, sonnet] : [sonnet, opus];
});

const builder = H.seat('builder').role(builderRole).models(sonnet, opus).policy(cheaperUntilWorse);
