  .exit(s => (s.steps.rounds.completed ? 'delivered' : 'roundsExhausted'));

const deliverBug = H.handler('deliver-bug')
  .of(bug)
  .flow(deliver, unit => ({ ...unit.data, rounds: 3 }))
