  { database: 'analytics', host: 'beta', resource: H.resource('analytics') },
];

const certificates: ReadonlyArray<z.infer<typeof renewalSchema>> = [
  { domain: 'example.com', host: 'alpha' },
  { domain: 'api.example.com', host: 'beta' },
];

