    Loading,
    Loaded,
    LoadedWithWarnings,
    Rejected,
    LoadFailed,
    Expired,
  )
  .key(load => `${load.source}:${load.night}`)
  .initial(Scheduled);

const warehouse = ssh.host('warehouse', { host: 'warehouse.internal', user: 'etl', key: H.env('ETL_SSH_KEY') }).slots(2);
